function openService(i){const title=t('sv'+i);$('#serviceTitle').textContent=title;$('#serviceSubtitle').textContent=SERVICE_COPY[i].sub[LI];$('#serviceFoot').textContent=SERVICE_COPY[i].foot[LI];$('#serviceBody').innerHTML=SVC_SAMPLE[i]();$('#serviceModal').showModal();}
