$('#serviceModal').addEventListener('click',e=>{if(e.target.id==='serviceModal')closeService()});
document.addEventListener('submit',e=>{
 if(e.target.matches('[data-demo-form]')){e.preventDefault();const out=e.target.querySelector('[data-form-result]');out.textContent=svTxt('تمت معاينة البيانات بنجاح. هذا نموذج تجريبي فقط ولم يُرسل أي طلب إلى المؤسسة.','Aperçu effectué. Il s’agit d’une démonstration : aucune demande n’a été envoyée à l’établissement.','Preview complete. This is a demo only; no request was sent to the institution.');out.classList.remove('hidden');return;}
 if(e.target.id==='librarySearch'){e.preventDefault();const q=$('#libQuery').value.trim().toLocaleLowerCase();let n=0;$$('[data-lib-card]').forEach(c=>{const show=!q||c.textContent.toLocaleLowerCase().includes(q);c.classList.toggle('hidden',!show);if(show)n++});if(!n)$('#libResults').innerHTML=`<p class="rounded-xl bg-white p-4 text-sm text-gray-600">${svTxt('لا توجد موارد مطابقة في العينة الحالية.','Aucune ressource correspondante dans cet échantillon.','No matching resources in this sample.')}</p>`;return;}
 if(e.target.id==='chatForm'){e.preventDefault();const q=$('#chatQuery').value.trim().toLowerCase();let ans;if(/تسجيل|inscript|register/.test(q))ans=svTxt('تابع إعلان التسجيل الرسمي وجهّز الوثائق المطلوبة وفق الآجال المنشورة.','Consultez l’annonce officielle et préparez les pièces selon les délais publiés.','Check the official registration notice and prepare the required documents by the published deadline.');else if(/امتحان|exam/.test(q))ans=svTxt('راجع إعلانات القسم والرزنامة الرسمية؛ المواعيد المعروضة هنا ليست رزنامة معتمدة.','Consultez les annonces du département et le calendrier officiel ; les dates affichées ici ne sont pas officielles.','Check department notices and the official calendar; dates shown here are not authoritative.');else if(/وثائق|document/.test(q))ans=svTxt('تختلف الوثائق حسب نوع الإجراء؛ تأكد من القائمة المنشورة أو استفسر من مصلحة الدراسة.','Les pièces dépendent de la démarche ; vérifiez la liste publiée ou contactez la scolarité.','Documents depend on the procedure; check the published list or contact student affairs.');else ans=svTxt('يمكنك تصفح خدمات الطالب والطلبات الإدارية والمكتبة الرقمية. للإجراء الرسمي، تواصل مع إدارة الملحقة.','Vous pouvez consulter l’espace étudiant, les demandes administratives et la bibliothèque. Pour une démarche officielle, contactez l’administration.','Explore Student Space, Administrative Requests and the Digital Library. Contact administration for official procedures.');$('#chatAnswer').textContent=ans;$('#chatAnswer').classList.remove('hidden');return;}
});
